def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    growth_percentage = (change / v1) * 100

    return {
        "value": growth_percentage,
        "trace": {
            "start_value": v1,
            "end_value": v2,
            "change": change,
            "growth_percentage": growth_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
